# 5.3 — -FilterXPath / -FilterXml và tách EventData thành đối tượng. XPath của Event Log = TẬP CON XPath 1.0 (chỉ dấu ngoặc [], and/or/not, =, !=, <, >, @thuộc-tính,
# hai hàm riêng timediff() và band()). Get-WinEventMau chấm XPath bằng .NET trên XML thật của từng bản ghi (bỏ namespace như Event Log làm).
@ps Get-WinEventMau mau/Archive-ForwardedEvents-test.evtx -FilterXPath "*[System[EventID=4625] and EventData[Data[@Name='SubStatus']='0xc000006a']]" | Measure-Object | Select-Object -ExpandProperty Count
@ps Get-WinEventMau mau/Archive-ForwardedEvents-test.evtx -FilterXPath "*[System[EventID=4625] and EventData[Data[@Name='SubStatus']!='0xc000006a']]" | Group-Object { $_.Properties[9].Value } | Format-Table Count, Name -AutoSize
@ps Get-WinEventMau mau/Archive-ForwardedEvents-test.evtx -FilterXPath "*[System[EventID=4624 and Computer='slad3.saclink.csus.edu']]" | Measure-Object | Select-Object -ExpandProperty Count
@ps Get-WinEventMau mau/Archive-ForwardedEvents-test.evtx -FilterXPath "*[System[EventID=4624]]" | Group-Object { $_.Properties[8].Value } | Sort-Object Count -Descending | Format-Table Count, @{n='LogonType'; e={$_.Name}} -AutoSize
@ps Get-WinEventMau mau/Archive-ForwardedEvents-test.evtx -FilterXPath "*[System[TimeCreated[timediff(@SystemTime) <= 600000]]]" -Now ([datetime]'2019-11-09 00:01:30') | Format-Table TimeCreated, Id, ProviderName -AutoSize
@ps Get-WinEventMau mau/Archive-ForwardedEvents-test.evtx -FilterXPath "*[EventData[Data[@Name='TargetUserName' and contains(., 'admin')]]]"
@ps $q = '<QueryList><Query Id="0"><Select Path="Security">*[System[EventID=4624 or EventID=4625]]</Select><Suppress Path="Security">*[EventData[Data[@Name="SubStatus"]="0xc0000064"]]</Suppress></Query></QueryList>'; Get-WinEventMau mau/Archive-ForwardedEvents-test.evtx -FilterXml $q | Group-Object Id, { $_.Properties[5].Value } | Sort-Object Count -Descending | Select-Object -First 6 Count, Name | Format-Table -AutoSize
@ps $q = '<QueryList><Query Id="0"><Select Path="Security">*[System[(EventID=4728 or EventID=4732 or EventID=4756)]]</Select><Select Path="Security">*[System[EventID=4720 or EventID=4738]]</Select></Query></QueryList>'; Get-WinEventMau mau/Archive-ForwardedEvents-test.evtx -FilterXml $q -Oldest | Format-Table TimeCreated, Id, MachineName -AutoSize
@ps function ConvertFrom-EventData { process { $o = [ordered]@{ Luc = $_.TimeCreated; Id = $_.Id; May = $_.MachineName }; foreach ($d in ([xml]$_.ToXml()).Event.EventData.Data) { $o[$d.Name] = $d.'#text' }; [pscustomobject]$o } }; Get-WinEventMau mau/Archive-ForwardedEvents-test.evtx -FilterXPath "*[System[EventID=4728 or EventID=4756]]" -Oldest | ConvertFrom-EventData | Format-Table Luc, Id, SubjectUserName, MemberName, TargetUserName -AutoSize
@ps (Get-WinEventMau tc/smb-doan-mk-4625.evtx -FilterXPath "Event/System[EventID=4625]").Count
